/testbed/cextern/wcslib/C/tab.h-*
/testbed/cextern/wcslib/C/tab.h-*   int m_flag
/testbed/cextern/wcslib/C/tab.h-*     (For internal use only.)
/testbed/cextern/wcslib/C/tab.h-*   int m_M
